var t=`0807-dovi`;var n=`world-0807`;var a=`ZW`;var s=`eastern-africa`;var o=4;var r=58;var g={en:`Dovi`,ua:`Дові`};var l={en:`Dovi is a Zimbabwe dish made with chicken thigh, yellow onion, tomato, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Дові, страва кухні країни Зімбабве. Основні складники: куряче стегно, жовта цибуля, помідор, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,750,`g`],[`canola-oil`,40,`ml`],[`yellow-onion`,180,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`tomato`,320,`g`],[`garlic`,4,`clove`],[`ground-cumin`,4,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`peanut-butter`,200,`g`],[`water`,600,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var d={slug:t,id:n,country:`ZW`,region:s,servings:4,minutes:58,title:g,text:l,steps:h};export{a as country,d as default,n as id,r as minutes,s as region,o as servings,t as slug,h as steps,l as text,g as title};